function refreshPlanWakeButton(){const b=document.querySelector('[data-plan-wake]');if(b)b.textContent=planWakeLock?'🔒 Açık':'🔓 Kapalı'}
async function releasePlanWake(){const lock=planWakeLock;planWakeLock=null;refreshPlanWakeButton();if(lock){try{await lock.release()}catch(_){}}}
async function togglePlanWake(){if(planWakeLock){await releasePlanWake();return}if(!navigator.wakeLock?.request){toast?.('Ekranı açık tutma bu cihazda desteklenmiyor.');return}try{const lock=await navigator.wakeLock.request('screen');planWakeLock=lock;lock.addEventListener?.('release',()=>{if(planWakeLock===lock){planWakeLock=null;refreshPlanWakeButton()}});refreshPlanWakeButton()}catch(_){toast?.('Ekranı açık tutma açılamadı.')}}
function openPlanWeekPicker(){const p=arr('yillikPlanTanimlari').find(x=>x.id===planView.planId);if(!p)return;const current=planCurrentWeekIndex(p),rows=p.satirlar||[],ov=modal('🗓 Haftaya Git',`<div class="ka-plan-week-picker">${rows.map((r,i)=>`<button class="ka-plan-week-choice ${i===planView.weekIndex?'active':''}" type="button" data-plan-jump="${i}"><span><strong>${esc(r.ay||`${i+1}. Hafta`)}</strong><small>${esc(planDateText(r,p.egitimOgretimYili)||r.hafta||`${i+1}. Hafta`)}</small></span>${i===current?'<span class="ka-badge">Bu Hafta</span>':''}</button>`).join('')||'<div class="ka-empty">Plan haftası bulunamadı.</div>'}</div>`);ov.querySelector('[data-save]').hidden=true;ov.querySelectorAll('[data-plan-jump]').forEach(b=>b.onclick=()=>{planView.weekIndex=Number(b.dataset.planJump)||0;ov.remove();render()})}
function openPlanWeekEditor(){const p=arr('yillikPlanTanimlari').find(x=>x.id===planView.planId);if(!p)return;const idx=planView.weekIndex,old=(p.satirlar||[])[idx]||{},vals=old.degerler||{},ov=modal('✏️ Bu Haftayı Düzenle',`<div class="ka-grid"><label class="ka-field"><span class="ka-field__label">Ay</span><input data-plan-week-month value="${esc(old.ay||'')}"></label><label class="ka-field"><span class="ka-field__label">Hafta</span><input data-plan-week-label value="${esc(old.hafta||'')}"></label><label class="ka-field"><span class="ka-field__label">Saat</span><input data-plan-week-hour value="${esc(old.saat||'')}"></label></div>${(p.sutunlar||[]).map(id=>`<label class="ka-field"><span class="ka-field__label">${esc(planHeadingName(id))}</span><textarea data-plan-week-value="${esc(id)}" rows="4">${esc(vals[id]||'')}</textarea></label>`).join('')}`);ov.querySelector('[data-save]').onclick=async()=>{const row={ay:ov.querySelector('[data-plan-week-month]').value.trim(),hafta:ov.querySelector('[data-plan-week-label]').value.trim(),saat:ov.querySelector('[data-plan-week-hour]').value.trim(),degerler:{}};ov.querySelectorAll('[data-plan-week-value]').forEach(x=>{const v=x.value.trim();if(v)row.degerler[x.dataset.planWeekValue]=v});const next=(p.satirlar||[]).slice();next[idx]=row;try{await YillikPlanService.goruntuAyarlariniKaydet(p.id,{satirlar:next});ov.remove();toast?.('Hafta güncellendi.')}catch(e){toast?.(e?.message==='yetkisiz'?'Bu işlem için yetkiniz yok.':'Hafta güncellenemedi.')}}}
