function openPlanRows(planId){const p=arr('yillikPlanTanimlari').find(x=>x.id===planId);if(!p)return;const rows=p.satirlar||[],ov=modal(`📋 ${esc(p.dersAdi||'Plan')} — Hafta Satırları`,`<div class="ka-plan-admin-list">${rows.length?rows.map((r,i)=>`<div class="ka-plan-admin-line"><span><b>${i+1}. ${esc(r.ay||'')}</b><small>${esc(planDateText(r,p.egitimOgretimYili)||r.hafta||'')}</small></span><div class="ka-row"><button class="ka-btn ka-btn--secondary ka-btn--sm" type="button" data-plan-row-edit="${i}">Düzenle</button><button class="ka-btn ka-btn--danger ka-btn--sm" type="button" data-plan-row-delete="${i}">Sil</button></div></div>`).join(''):'<div class="ka-empty">Henüz hafta satırı yok.</div>'}</div><button class="ka-btn" type="button" data-plan-row-new>＋ Yeni Hafta Ekle</button>`);ov.querySelector('[data-save]').hidden=true;ov.querySelector('[data-plan-row-new]').onclick=()=>{ov.remove();openPlanRowEditor(planId,null)};ov.querySelectorAll('[data-plan-row-edit]').forEach(b=>b.onclick=()=>{ov.remove();openPlanRowEditor(planId,Number(b.dataset.planRowEdit))});ov.querySelectorAll('[data-plan-row-delete]').forEach(b=>b.onclick=async()=>{if(!confirm('Bu hafta satırı silinsin mi?'))return;const next=rows.slice();next.splice(Number(b.dataset.planRowDelete),1);try{await YillikPlanService.tanimGuncelle(planId,{satirlar:next});ov.remove();openPlanRows(planId)}catch(e){toast?.('Hafta silinemedi.')}})}
