function closeAcademicCalendar(){academicCalendarUnsub?.();academicCalendarUnsub=null;academicCalendarOverlay?.remove();academicCalendarOverlay=null;revokeAcademicCalendarObjectUrl();document.body.classList.remove('modal-open')}
function academicCalendarTopBar(meta){const label=meta?.gorselUrl?'Değiştir':'Yükle';return `<div class="ka-academic-calendar__bar"><button class="ka-btn ka-btn--secondary ka-btn--sm" type="button" data-academic-calendar-close>← Kapat</button><div class="ka-academic-calendar__title"><strong>📅 Akademik Takvim</strong>${meta?.guncellenmeTarihi?`<small>${esc(calendarFmtDate(meta.guncellenmeTarihi))}${meta?.yukleyenAdi?` · ${esc(meta.yukleyenAdi)}`:''}</small>`:''}</div><div class="ka-academic-calendar__action">${calendarAdmin()?`<input type="file" accept="image/*" data-academic-calendar-file hidden><button class="ka-btn ka-btn--secondary ka-btn--sm" type="button" data-academic-calendar-pick>🖼️ ${label}</button>`:'<span class="ka-academic-calendar__spacer"></span>'}</div></div>`}
async function renderAcademicCalendarOverlay(meta=calendarMeta()){if(!academicCalendarOverlay)return;academicCalendarOverlay.innerHTML=`${academicCalendarTopBar(meta)}<div class="ka-academic-calendar__stage" data-academic-calendar-stage><div class="ka-muted" data-academic-calendar-loading>${meta?.gorselUrl?'Takvim hazırlanıyor…':'Henüz bir akademik takvim görseli yüklenmemiş.'}</div></div><div class="ka-academic-calendar__help">İki parmakla yakınlaştırın · yakınlaştırınca sürükleyin · çift dokunuşla hızlı yakınlaştırın</div>`;academicCalendarOverlay.querySelector('[data-academic-calendar-close]')?.addEventListener('click',closeAcademicCalendar);const input=academicCalendarOverlay.querySelector('[data-academic-calendar-file]');academicCalendarOverlay.querySelector('[data-academic-calendar-pick]')?.addEventListener('click',()=>input?.click());input?.addEventListener('change',()=>uploadAcademicCalendarImage(input.files?.[0],meta));if(!meta?.gorselUrl)return;const stage=academicCalendarOverlay.querySelector('[data-academic-calendar-stage]'),src=await academicCalendarCachedSource(meta);if(!academicCalendarOverlay||!stage)return;stage.innerHTML=`<img class="ka-academic-calendar__image" data-academic-calendar-image src="${esc(src)}" alt="Akademik Takvim" draggable="false">`;const img=stage.querySelector('[data-academic-calendar-image]');img?.addEventListener('error',()=>{if(stage?.isConnected)stage.innerHTML='<div class="ka-muted">Takvim görseli çevrimdışı kullanılamıyor. İnternet bağlantısı geldiğinde yeniden deneyin.</div>'},{once:true});bindAcademicCalendarGestures(stage,img);refreshAcademicCalendarCache(meta)}
async function uploadAcademicCalendarImage(file,previous=calendarMeta()){if(!file)return;if(!calendarAdmin()){toast?.('Bu işlem yalnızca yönetici tarafından yapılabilir.');return}if(!String(file.type||'').startsWith('image/')){toast?.('Lütfen bir görsel dosyası seçin.');return}const stage=academicCalendarOverlay?.querySelector('[data-academic-calendar-stage]');if(stage)stage.innerHTML='<div class="ka-muted" data-academic-calendar-progress>Yükleniyor… %0</div>';try{const next=await AkademikTakvimService.gorselYukle(file,p=>{const el=academicCalendarOverlay?.querySelector('[data-academic-calendar-progress]');if(el)el.textContent=`Yükleniyor… %${p}`},previous);await clearAcademicCalendarCache();toast?.('Akademik takvim güncellendi.');await renderAcademicCalendarOverlay(next)}catch(e){const msg=String(e?.message||e||'');if(msg.startsWith('depolama-siniri:'))toast?.(msg.slice('depolama-siniri:'.length));else if(msg!=='yetkisiz')toast?.('Yükleme hatası: '+msg);await renderAcademicCalendarOverlay(previous)}}
function subscribeAcademicCalendarOverlay(){academicCalendarUnsub?.();academicCalendarUnsub=AppStore?.subscribe?.('data.akademikTakvim',()=>{if(academicCalendarOverlay)requestAnimationFrame(()=>renderAcademicCalendarOverlay(calendarMeta()))})||null}
function openAcademicCalendar(meta=calendarMeta()){closeAcademicCalendar();academicCalendarOverlay=document.createElement('section');academicCalendarOverlay.id='kaAcademicCalendarOverlay';academicCalendarOverlay.setAttribute('role','dialog');academicCalendarOverlay.setAttribute('aria-modal','true');academicCalendarOverlay.setAttribute('aria-label','Akademik Takvim');academicCalendarOverlay.className='ka-academic-calendar-overlay';document.body.appendChild(academicCalendarOverlay);document.body.classList.add('modal-open');subscribeAcademicCalendarOverlay();renderAcademicCalendarOverlay(meta);return true}
function calendar(){const d=calendarMeta();return{count:d?1:0,html:`<section class="ka-stack"><article class="ka-card"><div class="ka-card__body ka-stack"><div class="ka-row ka-row--between"><div><strong>📅 Akademik Takvim</strong><div class="ka-muted">${esc(d?.dosyaAdi||d?.baslik||'Okul çalışma takvimi')}</div></div><button class="ka-btn ka-btn--secondary ka-btn--sm" type="button" data-academic-calendar-open>${d?.gorselUrl?'Tam Ekran Aç':'Takvimi Aç'}</button></div>${d?.gorselUrl?`<img class="ka-media" src="${esc(d.gorselUrl)}" alt="Akademik Takvim" loading="lazy">`:'<div class="ka-empty">Akademik takvim yüklenmemiş.</div>'}</div></article></section>`}}
function bindAcademicCalendar(out){out?.querySelector('[data-academic-calendar-open]')?.addEventListener('click',()=>openAcademicCalendar(calendarMeta()))}
function classes(){return[...arr('siniflar')].filter(x=>x.ad).sort((a,b)=>String(a.ad).localeCompare(String(b.ad),'tr',{numeric:true}))}
function teachers(){return[...arr('ogretmenler')].sort((a,b)=>`${a.ad||''} ${a.soyad||''}`.localeCompare(`${b.ad||''} ${b.soyad||''}`,'tr'))}
function teacherName(id){const o=arr('ogretmenler').find(x=>x.id===id);return o?`${o.ad||''} ${o.soyad||''}`.trim():'—'}
function lessonSettings(){return arr('dersSaatleri').find(x=>x.id==='ayarlar')||arr('dersSaatleri')[0]||null}
function fallbackTimes(){let m=8*60+30,out=[];for(let i=1;i<=7;i++){const s=m,e=m+40,p=n=>`${String(Math.floor(n/60)).padStart(2,'0')}:${String(n%60).padStart(2,'0')}`;out.push({saat:i,baslangic:p(s),bitis:p(e)});m=e+(i===4?50:10)}return out}
function lessonTimes(){const s=lessonSettings(),rows=Array.isArray(s?.donemler)&&s.donemler.length?s.donemler:fallbackTimes();return rows.map(x=>({saat:Number(x.saat),baslangic:x.baslangic||'',bitis:x.bitis||''})).sort((a,b)=>a.saat-b.saat)}
function minutes(v){if(!v||!String(v).includes(':'))return null;const[h,m]=String(v).split(':').map(Number);return Number.isFinite(h)&&Number.isFinite(m)?h*60+m:null}
function addMinutes(value,delta){if(!value)return'';const[h,m]=value.split(':').map(Number);if(!Number.isFinite(h)||!Number.isFinite(m))return'';let total=(h*60+m+Number(delta||0))%(24*60);if(total<0)total+=24*60;return`${String(Math.floor(total/60)).padStart(2,'0')}:${String(total%60).padStart(2,'0')}`}
function breakAfter(period){const rows=lessonTimes(),i=rows.findIndex(x=>x.saat===period),a=rows[i],b=rows[i+1];if(!a||!b)return null;const end=minutes(a.bitis),start=minutes(b.baslangic);if(end==null||start==null||start<=end)return null;const s=lessonSettings(),lunch=s?.ogleArasiVarMi!==false&&s?.ogleArasi&&s.ogleArasi.baslangic===a.bitis&&s.ogleArasi.bitis===b.baslangic;return{minutes:start-end,label:lunch?'Öğle Arası':'Teneffüs'}}
function canEditSchedule(){return !!DersProgramiService?._duzenleyebilir?.()}
function scheduleLessonIcon(ad){const t=String(ad||'').toLocaleLowerCase('tr');if(t.includes('fen'))return'🧪';if(t.includes('matematik'))return'✖️';if(t.includes('türk'))return'📘';if(t.includes('ingiliz'))return'🔤';if(t.includes('sosyal'))return'🌍';if(t.includes('din'))return'📖';if(t.includes('beden'))return'🏃';if(t.includes('müzik'))return'🎵';if(t.includes('görsel')||t.includes('resim'))return'🎨';if(t.includes('bilişim'))return'💻';return'📚'}
function scheduleMobile(){if(!DAYS.includes(selectedScheduleDay))selectedScheduleDay=todayScheduleDay();const entries=arr('dersProgrami').filter(x=>x.sinif===selectedClass),times=lessonTimes(),today=todayScheduleDay(),cards=[];for(let p=1;p<=7;p++){const e=entries.find(x=>x.gun===selectedScheduleDay&&Number(x.saat)===p),tm=times.find(x=>x.saat===p),br=breakAfter(p),time=tm?[tm.baslangic,tm.bitis].filter(Boolean).join('–'):'';cards.push(`<button type="button" class="ka-schedule-mobile-lesson ${e?'filled':'empty'}" data-schedule-cell data-day="${esc(selectedScheduleDay)}" data-period="${p}" data-entry="${esc(e?.id||'')}" ${canEditSchedule()?'':'disabled'}><span class="ka-schedule-mobile-period">${p}</span><span class="ka-schedule-mobile-time"><b>${esc(time||`${p}. ders`)}</b><small>${e?'Ders saati':'Boş saat'}</small></span><span class="ka-schedule-mobile-main">${e?`<i>${scheduleLessonIcon(e.ders)}</i><span><strong>${esc(e.ders||'Ders')}</strong><small>${esc(teacherName(e.ogretmenId)||'Öğretmen atanmadı')}</small></span>`:`<i>＋</i><span><strong>Ders Ekle</strong><small>${canEditSchedule()?'Bu saate ders ekleyin':'Ders bulunmuyor'}</small></span>`}</span><span class="ka-schedule-mobile-action">${e?'✎':'＋'}</span></button>`);if(br&&p<7)cards.push(`<div class="ka-schedule-mobile-break"><span>${br.label==='Öğle Arası'?'🍽️':'☕'}</span><strong>${esc(br.label)}</strong><small>${br.minutes} dk</small></div>`)}return `<section class="ka-schedule-mobile" aria-label="Mobil ders programı"><div class="ka-schedule-mobile-days">${DAYS.map(d=>`<button type="button" class="${d===selectedScheduleDay?'active':''} ${d===today?'today':''}" data-schedule-day="${esc(d)}"><b>${esc(d.slice(0,3))}</b>${d===today?'<small>Bugün</small>':'<small>&nbsp;</small>'}</button>`).join('')}</div><div class="ka-schedule-mobile-date">📅 <strong>${esc(selectedScheduleDay)}</strong><span>${esc(selectedClass||'Sınıf seçilmedi')}</span></div><div class="ka-schedule-mobile-list">${cards.join('')||'<div class="ka-empty">Bu gün için ders bulunamadı.</div>'}</div></section>`}
function scheduleGrid(){const c=classes();if(!selectedClass&&c.length)selectedClass=c[0].ad;if(selectedClass&&!c.some(x=>x.ad===selectedClass))selectedClass=c[0]?.ad||'';const entries=arr('dersProgrami').filter(x=>x.sinif===selectedClass),todayName=['Pazar','Pazartesi','Salı','Çarşamba','Perşembe','Cuma','Cumartesi'][new Date().getDay()],times=lessonTimes();let body='';for(let p=1;p<=7;p++){const tm=times.find(x=>x.saat===p),label=tm?`${p}. <span>${esc(tm.baslangic)}–${esc(tm.bitis)}</span>`:`${p}.`;body+=`<tr><th class="ka-schedule-time">${label}</th>${DAYS.map(day=>{const e=entries.find(x=>x.gun===day&&Number(x.saat)===p);return`<td class="ka-schedule-cell ${e?'filled':'empty'} ${day===todayName?'today':''}"><button type="button" data-schedule-cell data-day="${esc(day)}" data-period="${p}" data-entry="${esc(e?.id||'')}" ${canEditSchedule()?'':'disabled'}>${e?`<strong>${esc(e.ders||'')}</strong><small>${esc(teacherName(e.ogretmenId))}</small>`:'<span>＋</span>'}</button></td>`}).join('')}</tr>`;const br=breakAfter(p);if(br)body+=`<tr class="ka-schedule-break"><td colspan="6">${esc(br.label)} (${br.minutes} dk)</td></tr>`}return`<div class="ka-table-wrap ka-schedule-wrap"><table class="ka-schedule-table"><thead><tr><th>Saat</th>${DAYS.map(d=>`<th class="${d===todayName?'today':''}">${esc(d)}</th>`).join('')}</tr></thead><tbody>${body}</tbody></table></div>`}
function firstEmptySchedulePeriod(day=selectedScheduleDay){const used=new Set(arr('dersProgrami').filter(x=>x.sinif===selectedClass&&x.gun===day).map(x=>Number(x.saat)));return[1,2,3,4,5,6,7].find(x=>!used.has(x))||1}
function scheduleSchoolInfo(){const rows=arr('okulBilgileri'),x=rows.find(r=>r.id==='ayarlar')||rows[0]||{};return{okulAdi:x.okulAdi||x.ad||'Koruk İlkokulu - Ortaokulu'}}
function scheduleAcademicYear(){const d=new Date(),y=d.getFullYear(),start=d.getMonth()>=7?y:y-1;return`${start}-${start+1}`}
function scheduleStats(){const rows=arr('dersProgrami').filter(x=>x.sinif===selectedClass),teacherIds=new Set(rows.map(x=>x.ogretmenId).filter(Boolean));return{lessons:rows.length,teachers:teacherIds.size}}
function schedule(){const c=classes();if(!selectedClass&&c.length)selectedClass=c[0].ad;if(selectedClass&&!c.some(x=>x.ad===selectedClass))selectedClass=c[0]?.ad||'';const stats=scheduleStats(),editable=canEditSchedule();const editActions=editable?`<button class="ka-schedule-action" type="button" data-schedule-add data-ka-permission="academic.schedule.edit" data-ka-write="academic.schedule.edit"><span>＋</span><b>Ders Ekle</b><small>Seçili güne yeni ders</small></button><button class="ka-schedule-action" type="button" data-schedule-import data-ka-permission="academic.schedule.edit" data-ka-write="academic.schedule.edit"><span>⇧</span><b>Excel’den İçe Aktar</b><small>Toplu program yükle</small></button>`:'';return{count:stats.lessons,html:`<section class="ka-stack ka-schedule-page"><article class="ka-schedule-hero"><div class="ka-schedule-hero__top"><span class="ka-schedule-hero__icon">📅</span><div class="ka-schedule-hero__copy"><small>HAFTALIK PROGRAM</small><h2>Ders Programı</h2><p>Sınıf ve öğretmen programlarını düzenleyin; rapor ve çarşaf çıktıları aynı ekrandan hazırlayın.</p></div><div class="ka-schedule-hero__stats"><span><b>${stats.lessons}</b><small>ders</small></span><span><b>${stats.teachers}</b><small>öğretmen</small></span></div></div><label class="ka-schedule-class-picker"><span>Sınıf</span><select id="academicClassSelect" aria-label="Sınıf seçimi">${c.length?c.map(x=>`<option value="${esc(x.ad)}" ${x.ad===selectedClass?'selected':''}>${esc(x.ad)}</option>`).join(''):'<option value="">Sınıf eklenmedi</option>'}</select></label><div class="ka-schedule-actions">${editActions}<button class="ka-schedule-action" type="button" data-schedule-report ${selectedClass?'':'disabled'}><span>🖨</span><b>Ders Programı</b><small>Seçili sınıf A4 raporu</small></button><button class="ka-schedule-action" type="button" data-schedule-sheet-report ${c.length?'':'disabled'}><span>▦</span><b>Çarşaf / Toplu Rapor</b><small>Sınıf ve öğretmen toplu çıktı</small></button></div></article><article class="ka-card ka-schedule-surface"><div class="ka-card__body"><div class="ka-schedule-surface-head"><div><small>SEÇİLİ SINIF</small><h3>${esc(selectedClass||'Sınıf seçilmedi')}</h3><p>${editable?'Bir ders kartına veya boş saate dokunarak programı düzenleyin.':'Program salt okunur olarak gösteriliyor.'}</p></div><span>${stats.lessons} kayıt</span></div>${c.length?`${scheduleMobile()}${scheduleGrid()}`:'<div class="ka-empty">Ders programını görüntülemek için önce bir sınıf kaydı gerekli.</div>'}</div></article></section>`}}
function scheduleLessonAbbr(name){const n=String(name||'').trim(),ref=lessons().find(x=>String(x.ad||'').localeCompare(n,'tr',{sensitivity:'base'})===0);if(ref?.kisaltma)return String(ref.kisaltma).trim().toLocaleUpperCase('tr');const key=n.toLocaleLowerCase('tr'),map=[['matematik','MAT'],['türkçe','TÜR'],['fen bilimleri','FEN'],['fen','FEN'],['sosyal bilgiler','SOS'],['sosyal','SOS'],['ingilizce','İNG'],['din kültürü','DİN'],['din','DİN'],['beden eğitimi','BED'],['beden','BED'],['müzik','MÜZ'],['görsel sanatlar','GRS'],['resim','RES'],['bilişim','BİL'],['teknoloji','TEK'],['rehberlik','REH'],['tarih','TAR'],['coğrafya','COĞ'],['fizik','FİZ'],['kimya','KİM'],['biyoloji','BİY'],['yazarlık','YAZ'],['drama','DRM'],['spor','SPR']];for(const[k,v]of map)if(key.includes(k))return v;return n.slice(0,3).toLocaleUpperCase('tr')}
function scheduleTeacherInitials(id){const name=teacherName(id);return name&&name!=='—'?name.split(/\s+/).filter(Boolean).map(x=>x[0]?.toLocaleUpperCase('tr')||'').join(''):''}
function scheduleReportPeriodLabel(p){const t=lessonTimes().find(x=>x.saat===p),clock=t?[t.baslangic,t.bitis].filter(Boolean).join('–'):'';return`${p}. Ders${clock?`<small>${esc(clock)}</small>`:''}`}
function scheduleReportMetaHtml(meta,contextTitle){const shownTitle=meta.title&&meta.title!=='Ders Programı'?meta.title:contextTitle,rows=[];if(meta.showSchool&&meta.school)rows.push(`<strong class="ka-schedule-report-school">${esc(meta.school)}</strong>`);if(meta.showTitle&&shownTitle)rows.push(`<h1>${esc(shownTitle)}</h1>`);if(meta.showYear&&meta.year)rows.push(`<span>${esc(meta.year)} Eğitim Öğretim Yılı</span>`);if(meta.showSubtitle&&meta.subtitle)rows.push(`<small>${esc(meta.subtitle)}</small>`);return rows.length?`<header class="ka-schedule-report-head">${rows.join('')}</header>`:''}
function scheduleWeeklyClassTable(className){const rows=arr('dersProgrami').filter(x=>x.sinif===className);return`<table class="ka-schedule-report-table ka-schedule-report-weekly"><thead><tr><th>Ders Saati</th>${DAYS.map(d=>`<th>${esc(d)}</th>`).join('')}</tr></thead><tbody>${[1,2,3,4,5,6,7].map(p=>`<tr><th>${scheduleReportPeriodLabel(p)}</th>${DAYS.map(day=>{const d=rows.find(x=>x.gun===day&&Number(x.saat)===p);return`<td>${d?`<b>${esc(d.ders||'—')}</b><small>${esc(teacherName(d.ogretmenId))}</small>`:'—'}</td>`}).join('')}</tr>`).join('')}</tbody></table>`}
function scheduleWeeklyTeacherTable(teacherId){const rows=arr('dersProgrami').filter(x=>x.ogretmenId===teacherId);return`<table class="ka-schedule-report-table ka-schedule-report-weekly"><thead><tr><th>Ders Saati</th>${DAYS.map(d=>`<th>${esc(d)}</th>`).join('')}</tr></thead><tbody>${[1,2,3,4,5,6,7].map(p=>`<tr><th>${scheduleReportPeriodLabel(p)}</th>${DAYS.map(day=>{const d=rows.find(x=>x.gun===day&&Number(x.saat)===p);return`<td>${d?`<b>${esc(d.ders||'—')}</b><small>${esc(d.sinif||'—')}</small>`:'—'}</td>`}).join('')}</tr>`).join('')}</tbody></table>`}
function scheduleSheetClasses(names){return`<table class="ka-schedule-report-table ka-schedule-report-sheet"><thead><tr><th rowspan="2" class="ka-schedule-report-scope">Sınıf</th>${DAYS.map(d=>`<th colspan="7">${esc(d)}</th>`).join('')}</tr><tr>${DAYS.map(()=>[1,2,3,4,5,6,7].map(p=>`<th>${p}</th>`).join('')).join('')}</tr></thead><tbody>${names.map(name=>`<tr><th class="ka-schedule-report-scope">${esc(name)}</th>${DAYS.map(day=>[1,2,3,4,5,6,7].map(p=>{const d=arr('dersProgrami').find(x=>x.sinif===name&&x.gun===day&&Number(x.saat)===p);return`<td>${d?`<b>${esc(scheduleLessonAbbr(d.ders))}</b><small>${esc(scheduleTeacherInitials(d.ogretmenId))}</small>`:''}</td>`}).join('')).join('')}</tr>`).join('')}</tbody></table>`}
function scheduleSheetTeachers(ids){const list=teachers().filter(o=>ids.includes(String(o.id)));return`<table class="ka-schedule-report-table ka-schedule-report-sheet"><thead><tr><th rowspan="2" class="ka-schedule-report-scope">Öğretmen</th>${DAYS.map(d=>`<th colspan="7">${esc(d)}</th>`).join('')}</tr><tr>${DAYS.map(()=>[1,2,3,4,5,6,7].map(p=>`<th>${p}</th>`).join('')).join('')}</tr></thead><tbody>${list.map(o=>`<tr><th class="ka-schedule-report-scope">${esc(teacherName(o.id))}</th>${DAYS.map(day=>[1,2,3,4,5,6,7].map(p=>{const d=arr('dersProgrami').find(x=>String(x.ogretmenId)===String(o.id)&&x.gun===day&&Number(x.saat)===p);return`<td>${d?`<b>${esc(d.sinif||'—')}</b><small>${esc(scheduleLessonAbbr(d.ders))}</small>`:''}</td>`}).join('')).join('')}</tr>`).join('')}</tbody></table>`}
function defaultScheduleReportMeta(){return{school:scheduleSchoolInfo().okulAdi,title:'Ders Programı',year:scheduleAcademicYear(),subtitle:'',showSchool:true,showTitle:true,showYear:true,showSubtitle:false,yon:'yatay'}}
async function printScheduleReport(type,selection,meta=defaultScheduleReportMeta()){if(!global.ReportEngine?.printReport){toast?.('Rapor motoru hazır değil.');return false}let contextTitle='',table='';if(type==='tekSinif'){const name=String(selection||'');if(!name)return toast?.('Sınıf seçin.');contextTitle=`${name} Sınıfı Haftalık Ders Programı`;table=scheduleWeeklyClassTable(name)}else if(type==='tekOgretmen'){const id=String(selection||'');if(!id)return toast?.('Öğretmen seçin.');contextTitle=`${teacherName(id)} — Haftalık Ders Programı`;table=scheduleWeeklyTeacherTable(id)}else if(type==='tumSiniflar'){const names=Array.isArray(selection)?selection:[];if(!names.length)return toast?.('En az bir sınıf seçin.');contextTitle='Sınıflar Ders Programı';table=scheduleSheetClasses(names)}else if(type==='tumOgretmenler'){const ids=(Array.isArray(selection)?selection:[]).map(String);if(!ids.length)return toast?.('En az bir öğretmen seçin.');contextTitle='Öğretmenler Ders Programı';table=scheduleSheetTeachers(ids)}else return false;const body=`${scheduleReportMetaHtml(meta,contextTitle)}<div class="ka-schedule-report-wrap">${table}</div>`;await global.ReportEngine.printReport(contextTitle,body,{fileName:contextTitle,yon:meta.yon,logoGoster:false,tarihGoster:false,baslikGoster:false,compact:type==='tumSiniflar'||type==='tumOgretmenler',fontSize:type==='tumSiniflar'||type==='tumOgretmenler'?7:8.5,kenarBosluk:type==='tumSiniflar'||type==='tumOgretmenler'?4:7});return true}
function printScheduleSingleClass(name=selectedClass){return printScheduleReport('tekSinif',name,defaultScheduleReportMeta())}
function scheduleReportTypeCard(value,label,desc,checked=false){return`<label class="ka-schedule-report-type"><input type="radio" name="kaScheduleReportType" value="${value}" data-schedule-report-type ${checked?'checked':''}><span><b>${label}</b><small>${desc}</small></span></label>`}
function scheduleReportTitleRow(key,value,label,checked){return`<div class="ka-schedule-report-title-row"><input data-schedule-report-${key} value="${esc(value)}" placeholder="${esc(label)}"><label class="ka-check"><input type="checkbox" data-schedule-report-${key}-show ${checked?'checked':''}><span>Göster</span></label></div>`}
function openScheduleReportHub(initialType='tekSinif'){const cs=classes(),ts=teachers(),meta=defaultScheduleReportMeta(),body=`<div class="ka-schedule-report-intro"><span>📊</span><div><strong>Ders Programı Raporu</strong><small>Tekil programları veya sınıf/öğretmen çarşaflarını hazırlayın.</small></div></div><fieldset class="ka-schedule-report-section"><legend>Rapor Tipi</legend><div class="ka-schedule-report-types">${scheduleReportTypeCard('tekSinif','Tek Sınıf Programı','Seçili sınıfın haftalık programı',initialType==='tekSinif')}${scheduleReportTypeCard('tekOgretmen','Tek Öğretmen Programı','Öğretmenin haftalık programı',initialType==='tekOgretmen')}${scheduleReportTypeCard('tumSiniflar','Tüm Sınıflar Çarşaf','Sınıfları tek tabloda göster',initialType==='tumSiniflar')}${scheduleReportTypeCard('tumOgretmenler','Tüm Öğretmenler Çarşaf','Öğretmenleri tek tabloda göster',initialType==='tumOgretmenler')}</div></fieldset><fieldset class="ka-schedule-report-section"><legend>Sayfa Yönü</legend><div class="ka-schedule-report-orientation"><label class="ka-check"><input type="radio" name="kaScheduleReportOrientation" value="yatay" checked><span>Yatay (A4)</span></label><label class="ka-check"><input type="radio" name="kaScheduleReportOrientation" value="dikey"><span>Dikey (A4)</span></label></div></fieldset><fieldset class="ka-schedule-report-section"><legend>Başlık Bilgileri</legend><div class="ka-schedule-report-titles">${scheduleReportTitleRow('school',meta.school,'Okul adı',true)}${scheduleReportTitleRow('title',meta.title,'Rapor başlığı',true)}${scheduleReportTitleRow('year',meta.year,'Eğitim yılı',true)}${scheduleReportTitleRow('subtitle','','Alt başlık (isteğe bağlı)',false)}</div></fieldset><div class="ka-schedule-report-panel" data-schedule-report-panel="tekSinif"><label class="ka-field"><span class="ka-field__label">Sınıf Seç</span><select data-schedule-report-single-class>${cs.map(x=>`<option value="${esc(x.ad)}" ${x.ad===selectedClass?'selected':''}>${esc(x.ad)}</option>`).join('')}</select></label></div><div class="ka-schedule-report-panel" data-schedule-report-panel="tekOgretmen" hidden><label class="ka-field"><span class="ka-field__label">Öğretmen Seç</span><select data-schedule-report-single-teacher>${ts.map(o=>`<option value="${esc(o.id)}">${esc(teacherName(o.id))}</option>`).join('')}</select></label></div><div class="ka-schedule-report-panel" data-schedule-report-panel="tumSiniflar" hidden><span class="ka-field__label">Sınıfları Seç</span><div class="ka-schedule-report-checks" data-schedule-report-class-list>${cs.map(x=>`<label class="ka-check"><input type="checkbox" value="${esc(x.ad)}" checked><span>${esc(x.ad)}</span></label>`).join('')}</div></div><div class="ka-schedule-report-panel" data-schedule-report-panel="tumOgretmenler" hidden><span class="ka-field__label">Öğretmenleri Seç</span><div class="ka-schedule-report-checks ka-schedule-report-checks--teachers" data-schedule-report-teacher-list>${ts.map(o=>`<label class="ka-check"><input type="checkbox" value="${esc(o.id)}" checked><span>${esc(teacherName(o.id))}</span></label>`).join('')}</div></div>`;const ov=modal('Ders Programı Raporu',body,false);ov.classList.add('ka-schedule-report-backdrop');ov.querySelector('.ka-modal')?.classList.add('ka-schedule-report-modal');const showPanel=()=>{const type=ov.querySelector('[data-schedule-report-type]:checked')?.value||'tekSinif';ov.querySelectorAll('[data-schedule-report-panel]').forEach(p=>p.hidden=p.dataset.scheduleReportPanel!==type)};ov.querySelectorAll('[data-schedule-report-type]').forEach(r=>r.addEventListener('change',showPanel));showPanel();const save=ov.querySelector('[data-save]');if(save){save.textContent='🖨 Yazdır';save.onclick=async()=>{const type=ov.querySelector('[data-schedule-report-type]:checked')?.value||'tekSinif',reportMeta={school:ov.querySelector('[data-schedule-report-school]')?.value.trim()||'',title:ov.querySelector('[data-schedule-report-title]')?.value.trim()||'',year:ov.querySelector('[data-schedule-report-year]')?.value.trim()||'',subtitle:ov.querySelector('[data-schedule-report-subtitle]')?.value.trim()||'',showSchool:!!ov.querySelector('[data-schedule-report-school-show]')?.checked,showTitle:!!ov.querySelector('[data-schedule-report-title-show]')?.checked,showYear:!!ov.querySelector('[data-schedule-report-year-show]')?.checked,showSubtitle:!!ov.querySelector('[data-schedule-report-subtitle-show]')?.checked,yon:ov.querySelector('input[name="kaScheduleReportOrientation"]:checked')?.value||'yatay'};let selection='';if(type==='tekSinif')selection=ov.querySelector('[data-schedule-report-single-class]')?.value||'';else if(type==='tekOgretmen')selection=ov.querySelector('[data-schedule-report-single-teacher]')?.value||'';else if(type==='tumSiniflar')selection=[...ov.querySelectorAll('[data-schedule-report-class-list] input:checked')].map(x=>x.value);else selection=[...ov.querySelectorAll('[data-schedule-report-teacher-list] input:checked')].map(x=>x.value);try{save.disabled=true;const ok=await printScheduleReport(type,selection,reportMeta);if(ok)ov.remove()}catch(e){console.error('[Ders Programı/Rapor]',e);toast?.('Rapor hazırlanamadı: '+(e?.message||e))}finally{if(save.isConnected)save.disabled=false}}}return ov}
async function openScheduleImport(){if(!canEditSchedule())return toast?.('Bu işlem için yetkiniz yok.');try{if(!global.ClassicExcelParity?.importSchedule)await global.AppLoader?.loadScript?.('js/modules/classic-excel-parity.js');if(!global.ClassicExcelParity?.importSchedule)throw new Error('Excel içe aktarma servisi hazır değil.');let input=document.getElementById('kaScheduleExcelInput');if(!input){input=document.createElement('input');input.id='kaScheduleExcelInput';input.type='file';input.accept='.xlsx,.xls';input.hidden=true;input.addEventListener('change',async()=>{const file=input.files?.[0];input.value='';if(!file)return;try{await global.ClassicExcelParity.importSchedule(file)}catch(e){console.error('[Ders Programı/Excel]',e);toast?.('İçe aktarma hatası: '+(e?.message||e))}});document.body.appendChild(input)}input.click()}catch(e){toast?.(e?.message||'Excel içe aktarma açılamadı.')}}
function modal(title,body,hasDelete=false){document.getElementById('kaAcademicScheduleModal')?.remove();const ov=document.createElement('div');ov.id='kaAcademicScheduleModal';ov.className='ka-modal-backdrop';ov.innerHTML=`<section class="ka-modal"><div class="ka-modal__header"><strong>${esc(title)}</strong><button class="ka-icon-button" type="button" data-close aria-label="Kapat">×</button></div><div class="ka-modal__body ka-stack">${body}</div><div class="ka-modal__footer">${hasDelete?'<button class="ka-btn ka-btn--danger" type="button" data-delete>Sil</button>':''}<button class="ka-btn ka-btn--secondary" type="button" data-close>Vazgeç</button><button class="ka-btn" type="button" data-save>Kaydet</button></div></section>`;document.body.appendChild(ov);ov.querySelectorAll('[data-close]').forEach(b=>b.onclick=()=>ov.remove());return ov}
function scheduleModal(day,period,id){const existing=id?arr('dersProgrami').find(x=>x.id===id):null,ls=lessons(),ts=teachers(),lessonValue=existing?.ders||'',lessonKnown=ls.some(x=>x.ad===lessonValue),ov=modal(existing?'Ders Düzenle':'Ders Ekle',`<div class="ka-schedule-modal-intro"><span>${existing?'✎':'＋'}</span><div><small>${existing?'PROGRAM KAYDI':'YENİ DERS'}</small><strong>${existing?'Ders kaydını düzenleyin':'Programa ders ekleyin'}</strong><p>Sınıf, gün, saat, ders ve öğretmen bilgisini tek ekrandan yönetin.</p></div></div><div class="ka-schedule-form-grid"><label class="ka-field ka-schedule-form-class"><span class="ka-field__label">Sınıf</span><input value="${esc(selectedClass)}" disabled></label><label class="ka-field"><span class="ka-field__label">Gün</span><select data-day>${DAYS.map(x=>`<option value="${esc(x)}" ${x===(existing?.gun||day)?'selected':''}>${esc(x)}</option>`).join('')}</select></label><label class="ka-field"><span class="ka-field__label">Ders Saati</span><select data-period>${[1,2,3,4,5,6,7].map(x=>`<option value="${x}" ${x===Number(existing?.saat||period)?'selected':''}>${x}. Ders</option>`).join('')}</select></label><label class="ka-field"><span class="ka-field__label">Ders</span><select data-lesson><option value="">Seçiniz</option>${ls.map(x=>`<option value="${esc(x.ad)}" ${x.ad===lessonValue?'selected':''}>${esc(x.ad)}</option>`).join('')}${lessonValue&&!lessonKnown?`<option value="${esc(lessonValue)}" selected>${esc(lessonValue)}</option>`:''}</select></label><label class="ka-field ka-schedule-form-teacher"><span class="ka-field__label">Öğretmen</span><select data-teacher><option value="">Seçiniz</option>${ts.map(o=>`<option value="${esc(o.id)}" ${o.id===existing?.ogretmenId?'selected':''}>${esc(teacherName(o.id))}</option>`).join('')}</select></label></div>`,!!existing);ov.classList.add('ka-schedule-modal-backdrop');ov.querySelector('.ka-modal')?.classList.add('ka-schedule-modal');ov.querySelector('[data-save]').onclick=async()=>{const veri={sinif:selectedClass,gun:ov.querySelector('[data-day]').value,saat:Number(ov.querySelector('[data-period]').value),ders:ov.querySelector('[data-lesson]').value,ogretmenId:ov.querySelector('[data-teacher]').value};if(!veri.ders)return toast?.('Sınıf ve ders alanı zorunludur.');try{await DersProgramiService.kaydet(existing?.id||null,veri);ov.remove();toast?.('Ders programı kaydedildi.')}catch(e){const m=String(e?.message||e);if(m.startsWith('cakisma:')){const[,ad,sinif]=m.split(':');toast?.(`Çakışma: ${ad}, bu gün ve saatte zaten ${sinif} sınıfına giriyor.`)}else if(m==='slot-dolu')toast?.('Seçilen sınıfın bu gün ve saatinde zaten bir ders var.');else if(m!=='yetkisiz')toast?.('Ders kaydedilemedi: '+m)}};ov.querySelector('[data-delete]')?.addEventListener('click',async()=>{if(!confirm('Bu ders kaydını silmek istiyor musunuz?'))return;await DersProgramiService.sil(existing.id);ov.remove();toast?.('Ders kaydı silindi.')})}
function classChecks(selected=[]){const set=new Set(selected);return classes().length?classes().map(s=>`<label class="ka-check"><input type="checkbox" data-exam-class value="${esc(s.ad)}" ${set.has(s.ad)?'checked':''}><span>${esc(s.ad)}</span></label>`).join(''):'<div class="ka-muted">Önce sınıf ekleyin.</div>'}
